style.css:
@-moz-document domain("code.ptit.edu.vn") {
body {
    /* Sử dụng hình nền với kích thước bao phủ, đảm bảo hình ảnh lấp đầy toàn bộ màn hình */
    background: url('https://png.pngtree.com/background/20230517/original/pngtree-female-anime-character-sitting-under-a-pink-flowering-tree-picture-image_2640410.jpg') no-repeat center center fixed;
    background-size: cover;
  }

  /* Tạo hiệu ứng trong suốt và mờ cho các container nội dung */
  .container, .main-content, .problem-list, .table, .panel, .card {
    background: rgba(255, 255, 255, 0.1); /* Tăng độ trong suốt một chút */
    backdrop-filter: blur(10px); /* Tăng độ mờ để cải thiện khả năng đọc */
    border-radius: 10px;
    padding: 20px; /* Tăng padding để có không gian xung quanh nội dung */
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); /* Thêm bóng đổ nhẹ để tạo độ sâu */
  }

  /* Áp dụng hiệu ứng tương tự cho thanh menu */
  .navbar, .header, .top-bar {
    background: rgba(0, 0, 0, 0.3); /* Tăng độ trong suốt một chút */
    backdrop-filter: blur(8px);
  }

  /* Định kiểu bảng danh sách */
  .table th, .table td {
    background: rgba(255, 255, 255, 0.2); /* Tăng độ trong suốt một chút */
    padding: 10px; /* Thêm padding cho các ô bảng */
    border-bottom: 1px solid rgba(255, 255, 255, 0.1); /* Thêm đường viền dưới cho các ô bảng */
  }

  /* Cải thiện khả năng đọc bằng cách đặt màu chữ thành trắng và tăng độ tương phản */
  body, .container, .main-content, .problem-list, .table, .panel, .card {
    color: #fff;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5); /* Thêm bóng đổ văn bản để cải thiện độ tương phản */
  }

    /* Thêm padding cho các liên kết trong menu*/
    .navbar a, .header a, .top-bar a{
        padding: 8px;
    }
}
